<template><section class="max-w-2xl"><h2 class="text-2xl font-bold mb-6">{{ editing ? 'Chỉnh sửa tài khoản' : 'Tạo tài khoản Farm' }}</h2><form class="space-y-4" @submit.prevent="save"><div class="grid grid-cols-1 sm:grid-cols-2 gap-4"><label v-for="field in fields" :key="field.key" class="block text-sm">{{ field.label }}<input v-model="form[field.key]" :type="field.type || 'text'" class="mt-1 block w-full rounded bg-white/10 border border-white/20 p-2" :required="field.required" /></label></div><p v-if="error" class="text-error">{{ error }}</p><div class="flex gap-3"><button class="px-4 py-2 rounded bg-primary text-secondary font-semibold" :disabled="saving">{{ saving ? 'Đang lưu…' : 'Lưu' }}</button><router-link class="px-4 py-2 rounded bg-white/10" :to="{ name: 'admin-accounts' }">Hủy</router-link></div></form></section></template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { adminApi } from '../../api/adminService'
const route = useRoute(); const router = useRouter(); const editing = computed(() => Boolean(route.params.id)); const saving = ref(false); const error = ref(''); const form = reactive({ username:'', password:'', fullName:'', email:'', phone:'', role:'FARM', farmName:'', businessLicense:'', address:'', description:'' }); const fields = computed(() => editing.value ? [{key:'fullName',label:'Họ tên',required:true},{key:'email',label:'Email',type:'email',required:true},{key:'phone',label:'Số điện thoại',required:true}] : [{key:'username',label:'Tên đăng nhập',required:true},{key:'password',label:'Mật khẩu',type:'password',required:true},{key:'fullName',label:'Họ tên',required:true},{key:'email',label:'Email',type:'email',required:true},{key:'phone',label:'Số điện thoại',required:true},{key:'farmName',label:'Tên trang trại'},{key:'businessLicense',label:'Giấy phép kinh doanh'},{key:'address',label:'Địa chỉ'},{key:'description',label:'Mô tả'}])
onMounted(async () => { if (!editing.value) return; try { Object.assign(form, (await adminApi.account(route.params.id)).data) } catch (e) { error.value = 'Không thể tải tài khoản.' } })
const save = async () => { saving.value=true; error.value=''; try { if (editing.value) await adminApi.updateAccount(route.params.id, { fullName:form.fullName,email:form.email,phone:form.phone }); else await adminApi.createAccount(form); router.push({name:'admin-accounts'}) } catch (e) { error.value=e.response?.data?.message || 'Không thể lưu tài khoản.' } finally { saving.value=false } }
</script>
